import numpy as np
import networkx as nx

def remove_incoming_edges(graph, nodes):
    """Create a copy of graph with incoming edges to nodes removed."""
    G = graph.copy()
    if isinstance(nodes, str):
        nodes = [nodes]
    for node in nodes:
        G.remove_edges_from(list(G.in_edges(node)))
    return G

def is_d_separated(graph, X, Y, Z):
    """Check if X and Y are d-separated given Z in the graph."""
    try:
        return nx.d_separated(graph, set(X), set(Y), set(Z))
    except AttributeError:
        # Fallback for older networkx versions
        return nx.is_d_separator(graph, set(X), set(Y), set(Z))

def rule1_independence_check(graph, Y, X, Z, W):
    """Check if Rule 1 of do-calculus applies: Y ⊥ Z | X, W in G_{do(X)}"""
    G_do_x = remove_incoming_edges(graph, X)
    conditioning_set = set([X]) | set(W) if isinstance(W, list) else set([X, W])
    return is_d_separated(G_do_x, [Y], [Z], conditioning_set)

def rule2_independence_check(graph, Y, X, Z, W):
    """Check if Rule 2 of do-calculus applies: Y ⊥ Z | X, W in G_{do(X,Z)}"""
    G_do_xz = remove_incoming_edges(graph, [X, Z])
    conditioning_set = set([X]) | set(W) if isinstance(W, list) else set([X, W])
    return is_d_separated(G_do_xz, [Y], [Z], conditioning_set)

def rule3_independence_check(graph, Y, X, Z, W):
    """Check if Rule 3 of do-calculus applies."""
    G_do_x = remove_incoming_edges(graph, X)
    conditioning_set = set([X]) | set(W) if isinstance(W, list) else set([X, W])
    return is_d_separated(G_do_x, [Y], [Z], conditioning_set)

if __name__ == "__main__":
    G = nx.DiGraph()
    G.add_edges_from([('X', 'Y'), ('Z', 'Y'), ('Z', 'X')])
    print(f"Rule 1 applies: {rule1_independence_check(G, 'Y', 'X', 'Z', [])}")
    print(f"Rule 2 applies: {rule2_independence_check(G, 'Y', 'X', 'Z', [])}")
